-- Outbox dispatcher (P1-11) and notification inbox. Generated by prisma migrate diff, then reviewed;
-- the checks and the data step at the end are hand-written.

-- AlterTable
ALTER TABLE "platform"."outbox_event" ADD COLUMN     "actor_user_id" UUID,
ADD COLUMN     "dead_lettered_at" TIMESTAMPTZ(6);

-- CreateTable
CREATE TABLE "platform"."notification" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "event_id" UUID NOT NULL,
    "kind" TEXT NOT NULL,
    "params" JSONB NOT NULL,
    "link" TEXT,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "read_at" TIMESTAMPTZ(6),

    CONSTRAINT "notification_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "notification_user_id_company_id_created_at_id_idx" ON "platform"."notification"("user_id", "company_id", "created_at" DESC, "id" DESC);

-- CreateIndex
CREATE UNIQUE INDEX "notification_event_id_user_id_key" ON "platform"."notification"("event_id", "user_id");

-- AddForeignKey
ALTER TABLE "platform"."notification" ADD CONSTRAINT "notification_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "org"."company"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "platform"."notification" ADD CONSTRAINT "notification_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "iam"."user"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


ALTER TABLE "platform"."notification"
  ADD CONSTRAINT notification_kind_valid CHECK (kind IN (
    'journal_reversed', 'role_granted', 'role_revoked', 'role_changed', 'period_closed',
    'export_ready', 'export_failed')),
  ADD CONSTRAINT notification_params_object CHECK (jsonb_typeof(params) = 'object'),
  -- Only paths inside the company area (no scheme, host or "..") so a link can never redirect away.
  ADD CONSTRAINT notification_link_internal CHECK (link IS NULL OR link ~ '^[a-z][a-z-]*(/[0-9a-f-]{36})?$');

ALTER TABLE "platform"."outbox_event"
  ADD CONSTRAINT outbox_event_dead_letter_unpublished CHECK (dead_lettered_at IS NULL OR published_at IS NULL);

-- Events recorded before the dispatcher existed are marked as handled without notifying anyone:
-- they describe past actions, and delivering them now would flood inboxes with stale messages.
UPDATE "platform"."outbox_event" SET published_at = now() WHERE published_at IS NULL;
